"""Exact HTTP transport and loopback server lifecycle for linkvault."""

from __future__ import annotations

from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import re
import signal
import socket
import sqlite3
import sys
import threading
import traceback

from .core import APIError, Clock, RateLimiter, format_timestamp, valid_slug
from .storage import Store


class LinkVaultServer(ThreadingHTTPServer):
    # Join request workers before closing SQLite, including stalled body readers.
    daemon_threads = False
    request_queue_size = 128

    def __init__(self, *args, **kwargs):
        self._requests = set()
        self._requests_lock = threading.Lock()
        self._store_closed = False
        super().__init__(*args, **kwargs)

    def get_request(self):
        request, address = super().get_request()
        with self._requests_lock:
            self._requests.add(request)
        return request, address

    def shutdown_request(self, request):
        try:
            super().shutdown_request(request)
        finally:
            with self._requests_lock:
                self._requests.discard(request)

    def server_close(self):
        with self._requests_lock:
            requests = list(self._requests)
        for request in requests:
            try:
                request.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
        super().server_close()
        if hasattr(self, "store") and not self._store_closed:
            self.store.close()
            self._store_closed = True


def _invalid_constant(value):
    raise ValueError("not a JSON constant: " + value)


class Handler(BaseHTTPRequestHandler):
    # HTTP/1.0 closes every connection: early failures need not drain the body.
    def __getattr__(self, name):
        if name.startswith("do_"):
            return self._handle
        raise AttributeError(name)

    def _route(self):
        # BaseHTTPRequestHandler normalizes leading // in self.path. Do not use it.
        path = self.requestline.split()[1].partition("?")[0]
        method = self.command
        if method == "GET" and path == "/healthz":
            return "health", None
        if method == "POST" and path == "/v1/tokens":
            return "token", None
        if path == "/v1/links" and method in ("POST", "GET"):
            return ("create" if method == "POST" else "list"), None
        if path.startswith("/v1/links/") and method in ("GET", "DELETE"):
            slug = path[len("/v1/links/"):]
            if valid_slug(slug):
                return ("inspect" if method == "GET" else "delete"), slug
        if (method == "POST" and path == "/v1/admin/clock"
                and self.server.clock.is_fake):
            return "clock", None
        if method == "GET" and path.startswith("/") and valid_slug(path[1:]):
            return "resolve", path[1:]
        raise APIError(404, "not_found")

    def _body(self):
        value = self.headers.get("Content-Length")
        if value is None:
            length = 0
        else:
            try:
                if re.fullmatch(r"[0-9]+", value) is None:
                    raise ValueError
                length = int(value)
            except ValueError:
                raise APIError(400, "invalid_request", "invalid Content-Length") from None
        if length > 8192:
            raise APIError(413, "payload_too_large", headers={"Connection": "close"})
        return self.rfile.read(length)

    def _json(self, body):
        try:
            value = json.loads(body.decode("utf-8"), parse_constant=_invalid_constant)
        except (ValueError, UnicodeError):
            raise APIError(400, "invalid_json") from None
        if not isinstance(value, dict):
            raise APIError(400, "invalid_json")
        return value

    def _link(self, link):
        return {
            "slug": link["slug"],
            "url": link["url"],
            "short_url": f"http://127.0.0.1:{self.server.server_port}/{link['slug']}",
            "created_at": format_timestamp(link["created_at"]),
            "expires_at": (None if link["expires_at"] is None
                           else format_timestamp(link["expires_at"])),
            "clicks": link["clicks"],
            "last_clicked_at": (None if link["last_clicked_at"] is None
                                else format_timestamp(link["last_clicked_at"])),
        }

    def _dispatch(self):
        route, slug = self._route()
        store = self.server.store
        owner = None
        if route in ("token", "clock"):
            if self.headers.get("X-Admin-Key") != self.server.admin_key:
                raise APIError(401, "unauthorized")
        elif route in ("create", "list", "inspect", "delete"):
            owner = store.authenticate(self.headers.get("Authorization"))
            self.server.limiter.check(owner)
        body = self._body()
        if route == "health":
            return 200, {"status": "ok"}, {}
        if route == "token":
            issued = store.issue_token()
            return 201, {"token": issued["token"],
                         "created_at": format_timestamp(issued["created_at"])}, {}
        if route == "create":
            return 201, self._link(store.create_link(owner, self._json(body))), {}
        if route == "list":
            return 200, {"links": [self._link(link) for link in store.list_links(owner)]}, {}
        if route == "inspect":
            return 200, self._link(store.inspect_link(owner, slug)), {}
        if route == "delete":
            store.delete_link(owner, slug)
            return 204, None, {}
        if route == "resolve":
            return 302, None, {"Location": store.resolve(slug)}
        now = self.server.clock.set_now(self._json(body))
        return 200, {"now": format_timestamp(now)}, {}

    def _send(self, status, obj, headers):
        body = (b"" if obj is None else
                json.dumps(obj, separators=(",", ":"), ensure_ascii=True).encode("utf-8"))
        self.send_response(status)
        if obj is not None:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        for name, value in headers.items():
            if name == "Location":
                # D4: Latin-1 where representable, otherwise the original UTF-8 bytes.
                try:
                    value.encode("latin-1")
                except UnicodeEncodeError:
                    value = value.encode("utf-8").decode("latin-1")
            self.send_header(name, value)
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _handle(self):
        try:
            try:
                status, obj, headers = self._dispatch()
                self._send(status, obj, headers)
            except APIError as error:
                self._send(error.status, {"error": {"code": error.code,
                                                   "message": error.message}}, error.headers)
            except Exception:
                traceback.print_exc(file=sys.stderr)
                error = APIError(500, "internal")
                self._send(error.status, {"error": {"code": error.code,
                                                   "message": error.message}}, {})
        except (BrokenPipeError, ConnectionResetError):
            pass


def make_server(db, admin_key, port=8000, rate_limit=60, fake_clock=None):
    """Open a loopback server; caller runs serve_forever, then shutdown/server_close.

    server_close joins interrupted request workers and closes the owned Store.
    This factory does not install signals or print readiness.
    """
    clock = Clock(fake_clock)
    limiter = RateLimiter(clock, rate_limit)
    store = Store(db, clock)
    try:
        server = LinkVaultServer(("127.0.0.1", port), Handler)
    except Exception:
        store.close()
        raise
    server.store = store
    server.clock = clock
    server.limiter = limiter
    server.admin_key = admin_key
    return server


def serve(args) -> int:
    """Run on the main thread with CLI-validated db/admin_key/port/rate/clock args."""
    try:
        server = make_server(args.db, args.admin_key, args.port,
                             args.rate_limit, args.fake_clock)
    except (OSError, sqlite3.Error) as error:
        print(f"linkvault: {error}", file=sys.stderr)
        return 3
    stopping = threading.Event()

    def stop(signum, frame):
        if not stopping.is_set():
            stopping.set()
            # A signal runs on the serve_forever thread; shutdown must not.
            threading.Thread(target=server.shutdown, daemon=True).start()

    previous = {}
    signals = [signal.SIGINT, signal.SIGTERM]
    if hasattr(signal, "SIGBREAK"):
        signals.append(signal.SIGBREAK)
    try:
        for signum in signals:
            previous[signum] = signal.signal(signum, stop)
        print(f"LISTENING http://127.0.0.1:{server.server_port}", flush=True)
        server.serve_forever(poll_interval=0.1)
    finally:
        server.server_close()
        for signum, handler in previous.items():
            signal.signal(signum, handler)
    return 0

